        }
        size += 3;
        for (; size; size--) {
                if (buf_size < size) {
                        eprintf ("Invalid record (too short)\n");
                        return false;
                }
                checksum += buf[size - 1];
        }
        if (checksum) {
                // eprintf ("Invalid record checksum\n");
        }
        return !checksum ? true : false;
}
